with parsed as (select id, service, host, latency_ms, context, context['version'] as version, get_json_object(payload_json, '$.duration') as duration_text from app_logs) select id, duration_text, avg(latency_ms) over (partition by service, host order by latency_ms, id rows between 3 preceding and 1 preceding) as latency_ms_avg_3_prior, round(latency_ms / sum(latency_ms) over (partition by host), 4) as latency_ms_share from parsed;
